D = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "cleaned_data")
x = pd.read_csv(os.path.join(D, "xhs_notes_clean.csv"), dtype={"note_id": str})
x = x[x.note_id.isin(T)]
rows = pd.DataFrame({"file": "xhs_notes_clean.csv", "key": "note_id", "id": x.note_id, "orig_lang": "zh", "translated": "True",
                     "translated_by": "Claude (context-preserving; local food terms kept)", "text_original": x.text, "text_en": x.note_id.map(T)})
p = os.path.join(D, "translations_en.csv")
old = pd.read_csv(p, dtype=str, encoding="utf-8-sig")
old = old[old.file != "xhs_notes_clean.csv"]
pd.concat([old, rows], ignore_index=True).to_csv(p, index=False, encoding="utf-8-sig")
